Object.entries(PRICING_TRANSLATIONS).forEach(([lang,copy])=>{if(lang!=='en')Object.assign(L[lang],copy)});
/* One calculation path for cards, service budgets and the estimator. No numeric fallback. */
function positiveNumber(v){return typeof v==='number'&&Number.isFinite(v)&&v>0}
function validPricing(c){
  if(!c||typeof c!=='object'||!/^Q[1-4] \d{4}$/.test(c.price_date)||typeof c.vat_construction!=='number'||!Number.isFinite(c.vat_construction)||c.vat_construction<0||!positiveNumber(c.rounding)||!positiveNumber(c.per_m2_display_rounding)||typeof c.contingency_note_pct!=='number'||!Number.isFinite(c.contingency_note_pct)||c.contingency_note_pct<0)return false;
  if(!c.area_limits||!positiveNumber(c.area_limits.min)||!positiveNumber(c.area_limits.max)||c.area_limits.min>c.area_limits.max)return false;
  if(!c.categories||!c.spec_factor||!c.location_factor||!positiveNumber(c.spec_factor.standard)||!positiveNumber(c.location_factor.dublin))return false;
  if(!Object.values(c.spec_factor).every(positiveNumber)||!Object.values(c.location_factor).every(positiveNumber))return false;
  if(!['show_case_prices','show_spec_input','show_location_input'].every(k=>typeof c[k]==='boolean'))return false;
  return ['refurb_with_extension','extension','new_home','refurb_only'].every(k=>{
    const x=c.categories[k];return x&&typeof x.enabled==='boolean'&&positiveNumber(x.low)&&positiveNumber(x.high)&&x.low<=x.high&&Array.isArray(x.card_area)&&x.card_area.length===2&&x.card_area.every(a=>positiveNumber(a)&&a>=c.area_limits.min&&a<=c.area_limits.max)&&x.card_area[0]<=x.card_area[1];
  });
}
function calculateBudget(c,key,area,spec='standard',location='dublin'){
  if(!validPricing(c)||!Object.hasOwn(c.categories,key)||!c.categories[key].enabled||!positiveNumber(area)||area<c.area_limits.min||area>c.area_limits.max||!Object.hasOwn(c.spec_factor,spec)||!Object.hasOwn(c.location_factor,location))return null;
  const x=c.categories[key],f=c.spec_factor[spec]*c.location_factor[location]*(1+c.vat_construction),r=c.rounding,p=c.per_m2_display_rounding;
  const out={low:Math.floor(area*x.low*f/r)*r,high:Math.ceil(area*x.high*f/r)*r,per_m2_low:Math.round(x.low*f/p)*p,per_m2_high:Math.round(x.high*f/p)*p};
  return Object.values(out).every(Number.isFinite)?out:null;
}
