function pricingText(key,values={}){return trs(key).replace(/\{([A-Za-z0-9_]+)\}/g,(m,k)=>Object.hasOwn(values,k)?String(values[k]):m)}
function pricingLocale(){return {en:'en-IE',fr:'fr-FR',de:'de-DE',it:'it-IT',es:'es-ES','zh-Hans':'zh-CN','zh-Hant':'zh-TW',ja:'ja-JP'}[LANG]||'en-IE'}
function pricingNumber(n){return new Intl.NumberFormat(pricingLocale(),{maximumFractionDigits:2}).format(n)}
function pricingMoney(n){return new Intl.NumberFormat(pricingLocale(),{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n)}
function pricingPercent(n){return new Intl.NumberFormat(pricingLocale(),{style:'percent',maximumFractionDigits:2}).format(n)}
function pricingQuarter(){const [q,y]=pricingConfig.price_date.split(' ');return pricingText('{quarter} {year}',{quarter:trs(q),year:y})}
function pricingDisclaimer(){return pricingText(PRICING_DISCLAIMER,{vat:pricingPercent(pricingConfig.vat_construction),quarter:pricingQuarter(),contingency:pricingPercent(pricingConfig.contingency_note_pct/100)})}
function pricingNode(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}
function pricingLegal(root){root.appendChild(pricingNode('p',pricingText('incl. VAT at {vat}',{vat:pricingPercent(pricingConfig.vat_construction)})+' · '+pricingQuarter(),'pricing-meta'));root.appendChild(pricingNode('p',pricingDisclaimer(),'pricing-disclaimer'))}
function pricingLink(root,key='Book a survey',prefill=false){const a=pricingNode('a',trs(key),'link');a.href='#contact';if(prefill)a.addEventListener('click',prefillEstimate);if(root.closest('#svcDlg'))a.addEventListener('click',()=>dlg.close());root.appendChild(a);return a}
function cardValues(key){const x=pricingConfig.categories[key],lo=calculateBudget(pricingConfig,key,x.card_area[0],pricingState.spec,pricingState.location),hi=calculateBudget(pricingConfig,key,x.card_area[1],pricingState.spec,pricingState.location);if(!lo||!hi)return null;
return {card_low:pricingMoney(lo.low),card_high:pricingMoney(hi.high),area_low:pricingNumber(x.card_area[0]),area_high:pricingNumber(x.card_area[1]),area:pricingNumber(x.card_area[0]),bedrooms:positiveNumber(pricingConfig.copy_facts?.new_home_bedrooms)?new Intl.NumberFormat(pricingLocale()).format(pricingConfig.copy_facts.new_home_bedrooms):'',per_m2_low:pricingMoney(lo.per_m2_low),per_m2_high:pricingMoney(lo.per_m2_high)}}
function renderPricingCards(){document.querySelectorAll('#pks .tile').forEach(tile=>{
  tile.querySelector('[data-pricing-root]')?.remove();const id=tile.dataset.id,root=pricingNode('div',undefined,'card-budget');root.dataset.pricingRoot='';
  if(id==='protected'){root.appendChild(pricingNode('p',trs('Budget set after a conservation assessment'),'pricing-line'));pricingLink(root,'Book a conservation assessment')}
  else{const key=pricingMap[id];if(!key||!pricingConfig||!pricingConfig.categories[key].enabled||!pricingCopy[key])return;const v=cardValues(key);if(!v)return;root.appendChild(pricingNode('p',pricingText(pricingCopy[key].card,v),'pricing-line'));pricingLegal(root);const b=pricingNode('button',trs('Budget details'),'link');b.type='button';b.addEventListener('click',()=>openSvc(key==='new_home'?'newbuild':key==='extension'?'extension':'refurb',key));root.appendChild(b)}
  tile.insertBefore(root,tile.querySelector('.open'));
})}
function renderServiceBudget(id,context){const root=document.getElementById('dlgBudgetWrap');root.replaceChildren();root.hidden=true;
  if(id==='protected'){root.hidden=false;root.appendChild(pricingNode('h3',trs('Budget')));root.appendChild(pricingNode('p',trs(PROTECTED_BUDGET)));pricingLink(root,'Book a conservation assessment');return}
  const key=context||({refurb:'refurb_only',extension:'extension',newbuild:'new_home'}[id]);if(!key||!pricingConfig||!pricingConfig.categories[key]?.enabled||!pricingCopy[key])return;const v=cardValues(key);if(!v)return;
  root.hidden=false;root.appendChild(pricingNode('h3',trs('Starting budget')));root.appendChild(pricingNode('p',pricingText('From {per_m2_low} per m² incl. VAT. Your scope, structure and finishes determine the final budget.',v),'pricing-line'));
  const ph=pricingConfig.placeholders||{},extras=positiveNumber(ph.NEWBUILD_EXTRAS_PCT)?pricingText(' and typically add {NEWBUILD_EXTRAS_PCT}',{NEWBUILD_EXTRAS_PCT:pricingPercent(ph.NEWBUILD_EXTRAS_PCT/100)}):'';
  root.appendChild(pricingNode('p',pricingText(pricingCopy[key].budget,{...v,extras})));
  pricingLegal(root);pricingLink(root);
}
function syncPricingSelect(id,options,value){const s=document.getElementById(id);if(JSON.stringify([...s.options].map(o=>o.value))!==JSON.stringify(options.map(o=>o[0]))){s.replaceChildren(...options.map(([v,t])=>{const o=pricingNode('option');o.value=v;return o}))}options.forEach(([v,t],i)=>s.options[i].textContent=trs(t));s.value=value}
function currentEstimate(){const raw=document.getElementById('budget-area').value;return raw.trim()?calculateBudget(pricingConfig,pricingState.category,Number(raw),pricingState.spec,pricingState.location):null}
function renderEstimator(){const root=document.getElementById('budgetEstimator'),fields=document.getElementById('budgetFields'),result=document.getElementById('budgetResult'),fallback=document.getElementById('budgetFallback'),isProtected=user.has('protected');
  root.querySelectorAll('[data-price-label]').forEach(el=>el.textContent=trs(el.dataset.priceLabel));
  result.replaceChildren();fallback.replaceChildren();document.getElementById('budgetError').textContent='';document.getElementById('budget-area').removeAttribute('aria-invalid');
  const keys=pricingConfig?Object.keys(pricingNames).filter(k=>pricingConfig.categories[k].enabled):[];
  fields.hidden=isProtected||!pricingConfig||!keys.length;document.getElementById('budgetBasis').hidden=isProtected;fallback.hidden=false;
  if(isProtected){pricingLink(fallback,'Book a conservation assessment');return}
  if(!pricingConfig||!keys.length){pricingLink(fallback);return}
  if(!keys.includes(pricingState.category))pricingState.category=keys[0];syncPricingSelect('budget-category',keys.map(k=>[k,pricingNames[k]]),pricingState.category);
  const specLabels={essential:'Essential',standard:'Standard',premium:'Premium'},locLabels={dublin:'Dublin',kildare_meath_wicklow:'Kildare, Meath & Wicklow',other_leinster:'Other Leinster'};
  document.getElementById('budgetSpecField').hidden=!pricingConfig.show_spec_input;document.getElementById('budgetLocationField').hidden=!pricingConfig.show_location_input;
  syncPricingSelect('budget-spec',Object.keys(pricingConfig.spec_factor).map(k=>[k,specLabels[k]||k]),pricingState.spec);syncPricingSelect('budget-location',Object.keys(pricingConfig.location_factor).map(k=>[k,locLabels[k]||k]),pricingState.location);
  const input=document.getElementById('budget-area');input.min=pricingConfig.area_limits.min;input.max=pricingConfig.area_limits.max;
  const calc=currentEstimate();if(!calc){if(input.value){document.getElementById('budgetError').textContent=trs('Please contact us');input.setAttribute('aria-invalid','true')}pricingLink(fallback);return}
  fallback.hidden=true;result.appendChild(pricingNode('p',pricingText('From {low} incl. VAT',{low:pricingMoney(calc.low)}),'pricing-result'));result.appendChild(pricingNode('p',pricingText('Indicative range: {low} – {high}',{low:pricingMoney(calc.low),high:pricingMoney(calc.high)}),'pricing-range'));pricingLegal(result);pricingLink(result,'Get your fixed price → book a survey',true);
  if(pricingCopy[pricingState.category]){const b=pricingNode('button',trs('Budget details'),'link');b.type='button';b.addEventListener('click',()=>openSvc(pricingState.category==='new_home'?'newbuild':pricingState.category==='extension'?'extension':'refurb',pricingState.category));result.appendChild(b)}
}
function prefillEstimate(){const calc=currentEstimate();if(!calc||user.has('protected'))return;const key=Object.keys(pricingMap).find(k=>pricingMap[k]===pricingState.category);selectPlanType(key);
  const m=document.getElementById('f-msg'),body=estimatorPrefix&&m.value.startsWith(estimatorPrefix)?m.value.slice(estimatorPrefix.length).replace(/^\n+/,''):m.value;
  estimatorPrefix=pricingText('Estimator: {project_type}, {area} m², {low}–{high}',{project_type:trs(pricingNames[pricingState.category]),area:pricingNumber(Number(document.getElementById('budget-area').value)),low:pricingMoney(calc.low),high:pricingMoney(calc.high)});m.value=estimatorPrefix+(body?'\n'+body:'');
  if(window.AmbiensUI)window.AmbiensUI.prepareEstimate();
  /* f-area is Area or Eircode (postal-code), so floor area belongs only in the message. */
}
function renderPricingCases(){const root=document.getElementById('pricingCases');root.replaceChildren();root.hidden=true;if(!pricingConfig||!Array.isArray(pricingConfig.case_studies))return;
  pricingConfig.case_studies.forEach((c,i)=>{if(!positiveNumber(c.total_area))return;const article=pricingNode('article',undefined,'pricing-case');article.appendChild(pricingNode('h3',i===0?trs('Extension & whole-house refurbishment — South County Dublin'):pricingText('Extension & whole-house refurbishment — {location}',{location:c.location})));
  article.appendChild(pricingNode('p',positiveNumber(c.house_area)&&positiveNumber(c.room_area)?pricingText('{total_area} m² ({house_area} m² house + {room_area} m² multi-function room)',{total_area:pricingNumber(c.total_area),house_area:pricingNumber(c.house_area),room_area:pricingNumber(c.room_area)}):pricingText('{area} m²',{area:pricingNumber(c.total_area)}),'pricing-case-area'));
  if(pricingConfig.show_case_prices&&positiveNumber(c.estimate_incl_vat)&&/^Sep \d{4}$/.test(c.estimate_date)){const [m,y]=c.estimate_date.split(' ');article.appendChild(pricingNode('p',pricingText('Contractor estimate, {estimate_date}: {case_total} incl. VAT (≈ {case_per_m2}/m²)',{estimate_date:pricingText('{month} {year}',{month:trs(m),year:y}),case_total:pricingMoney(c.estimate_incl_vat),case_per_m2:pricingMoney(c.estimate_incl_vat/c.total_area)}),'pricing-line'));pricingLegal(article)}
  article.appendChild(pricingNode('p',trs(i===0?'Strip-out, single-storey warm-roof extension, first-floor extension on steel, new plaster throughout, oak-style joinery, drainage and driveway.':'Same scope as above on a smaller home — fixed costs raise the rate per m².')));if(i===0)article.appendChild(pricingNode('p',trs('Windows, electrical and plumbing carried as provisional sums.')));root.appendChild(article)});
  if(root.children.length){root.hidden=false;root.appendChild(pricingNode('p',trs('Estimates are pre-contract contractor estimates, not final accounts.'),'pricing-case-caption'))}
}
function renderPricingPlaceholders(){['joineryPrice','designPrice','surveyPrice'].forEach(id=>{const e=document.getElementById(id);e.hidden=true;e.replaceChildren()});if(!pricingConfig)return;
  const ph=pricingConfig.placeholders||{};let e;
  if(positiveNumber(ph.BOLONI_KITCHEN_FROM)&&positiveNumber(ph.BOLONI_WARDROBE_FROM)){e=document.getElementById('joineryPrice');e.hidden=false;e.appendChild(pricingNode('p',pricingText('Kitchens from {BOLONI_KITCHEN_FROM} · Wardrobes from {BOLONI_WARDROBE_FROM}',{BOLONI_KITCHEN_FROM:pricingMoney(ph.BOLONI_KITCHEN_FROM),BOLONI_WARDROBE_FROM:pricingMoney(ph.BOLONI_WARDROBE_FROM)}),'pricing-line'));pricingLegal(e)}
  if(positiveNumber(ph.DESIGN_FEE_PCT)){e=document.getElementById('designPrice');e.hidden=false;e.appendChild(pricingNode('p',pricingText('Design & planning fees typically {DESIGN_FEE_PCT} of build cost — fixed fee agreed after survey',{DESIGN_FEE_PCT:pricingPercent(ph.DESIGN_FEE_PCT/100)})));pricingLegal(e)}
  if(positiveNumber(ph.SURVEY_FEE)){e=document.getElementById('surveyPrice');e.hidden=false;const s=pricingNode('div',undefined,'shell');s.appendChild(pricingNode('h2',trs('Know your number before you commit.')));s.appendChild(pricingNode('p',pricingText('Fixed-fee survey & cost plan — {SURVEY_FEE}{SURVEY_CREDIT_TEXT}',{SURVEY_FEE:pricingMoney(ph.SURVEY_FEE),SURVEY_CREDIT_TEXT:typeof ph.SURVEY_CREDIT_TEXT==='string'?trs(ph.SURVEY_CREDIT_TEXT):''}),'pricing-line'));s.appendChild(pricingNode('p',trs('You get measured drawings, a scope of works and a costed budget for your home.')));pricingLegal(s);pricingLink(s);e.appendChild(s)}
}
function refreshPricing(){if(!pricingLoaded)return;renderPricingCards();renderEstimator();renderPricingCases();renderPricingPlaceholders();if(dlg.open)renderServiceBudget(dlgId,dlgPricingCategory)}
['category','spec','location'].forEach(k=>document.getElementById('budget-'+k).addEventListener('change',e=>{pricingState[k]=e.target.value;refreshPricing()}));document.getElementById('budget-area').addEventListener('input',renderEstimator);
refreshPricing();
(async()=>{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{let c;if(location.protocol==='file:'){c=JSON.parse(document.getElementById('local-pricing').textContent)}else{const res=await fetch('data/pricing.json',{cache:'no-store',signal:controller.signal});if(!res.ok)throw new Error('Pricing unavailable');c=await res.json();}if(!validPricing(c))throw new Error('Invalid pricing');pricingConfig=c}catch(e){pricingConfig=null}finally{clearTimeout(timeout);pricingLoaded=true;refreshPricing()}})();

